-- Deterministic sample DB for PG Backup Studio tests (no random()/now()).
SET client_min_messages = warning;

CREATE EXTENSION citext;
CREATE EXTENSION btree_gist;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'pgbs_test_reader') THEN
    CREATE ROLE pgbs_test_reader LOGIN;
  END IF;
END $$;

CREATE SCHEMA app;
CREATE SCHEMA "sales data";
CREATE SCHEMA audit;

-- types
CREATE TYPE app.mood AS ENUM ('happy', 'it''s "meh"', 'sad');
CREATE DOMAIN app.posint AS integer CHECK (VALUE > 0);
CREATE TYPE app.address AS (street text, city text, zip varchar(10));
CREATE TYPE app.floatrange AS RANGE (subtype = float8, subtype_diff = float8mi);

-- standalone sequence with options
CREATE SEQUENCE app.ticket_seq START WITH 100 INCREMENT BY 5 MINVALUE 10 MAXVALUE 100000 CACHE 3 CYCLE;
SELECT setval('app.ticket_seq', 150) \gset

-- customers: serial, citext, domain, enum, composite, range, generated, collation, self FK
CREATE TABLE app.customers (
  id serial PRIMARY KEY,
  email citext NOT NULL UNIQUE,
  name text COLLATE "C" NOT NULL,
  mood app.mood DEFAULT 'happy',
  score app.posint,
  addr app.address,
  band app.floatrange,
  first_name text,
  last_name text,
  full_name text GENERATED ALWAYS AS (first_name || ' ' || last_name) STORED,
  referrer_id integer REFERENCES app.customers(id)
);
COMMENT ON TABLE app.customers IS 'Customers with ''quotes'' and "double quotes"';
COMMENT ON COLUMN app.customers.name IS 'it''s a "name"';

INSERT INTO app.customers (email, name, mood, score, addr, band, first_name, last_name)
SELECT 'User' || i || '@Example.com', 'name ' || i,
       (ARRAY['happy','it''s "meh"','sad'])[1 + i % 3]::app.mood,
       i, ROW('street ' || i, 'city ' || (i % 7), NULL)::app.address,
       app.floatrange(i::float8, i + 1.5::float8), 'First' || i, 'Last' || i
FROM generate_series(1, 50) i;
UPDATE app.customers SET referrer_id = 1 + (id - 1) % 5 WHERE id > 5;

-- identity ALWAYS / BY DEFAULT with options
CREATE TABLE app.ident_always (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  v text
);
INSERT INTO app.ident_always (v) SELECT 'a' || i FROM generate_series(1, 7) i;

CREATE TABLE app.ident_default (
  id integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1000 INCREMENT BY 10 MINVALUE 500 MAXVALUE 99999 CACHE 2) PRIMARY KEY,
  v text
);
INSERT INTO app.ident_default (v) SELECT 'd' || i FROM generate_series(1, 4) i;
INSERT INTO app.ident_default (id, v) VALUES (5, 'explicit');

-- exclusion constraint via btree_gist
CREATE TABLE app.bookings (
  id serial PRIMARY KEY,
  room integer NOT NULL,
  during int4range NOT NULL,
  EXCLUDE USING gist (room WITH =, during WITH &&)
);
INSERT INTO app.bookings (room, during) VALUES (1, '[1,5)'), (1, '[5,9)'), (2, '[1,9)');

-- range-partitioned orders (reserved word as column name)
CREATE TABLE "sales data".orders (
  id bigint NOT NULL,
  customer_id integer NOT NULL REFERENCES app.customers(id),
  "order" text,
  amount numeric(12,2) NOT NULL,
  ordered_at timestamp NOT NULL,
  PRIMARY KEY (id, ordered_at)
) PARTITION BY RANGE (ordered_at);
CREATE TABLE "sales data".orders_2024q1 PARTITION OF "sales data".orders
  FOR VALUES FROM ('2024-01-01') TO ('2024-04-01');
CREATE TABLE "sales data".orders_2024q2 PARTITION OF "sales data".orders
  FOR VALUES FROM ('2024-04-01') TO ('2024-07-01');
CREATE TABLE "sales data".orders_default PARTITION OF "sales data".orders DEFAULT;
CREATE INDEX orders_customer_idx ON "sales data".orders (customer_id);

INSERT INTO "sales data".orders (id, customer_id, "order", amount, ordered_at)
SELECT i, 1 + i % 50, 'order #' || i, (i % 1000) + 0.25,
       timestamp '2024-01-01 00:00:00' + (i * interval '2 hours')
FROM generate_series(1, 5000) i;

-- child table with FK to the partitioned table (candidate for NOT VALID)
CREATE TABLE "sales data"."order lines" (
  id serial PRIMARY KEY,
  order_id bigint NOT NULL,
  ordered_at timestamp NOT NULL,
  qty integer,
  FOREIGN KEY (order_id, ordered_at) REFERENCES "sales data".orders (id, ordered_at)
);
INSERT INTO "sales data"."order lines" (order_id, ordered_at, qty)
SELECT i, timestamp '2024-01-01' + (i * interval '2 hours'), i % 9 FROM generate_series(1, 300) i;

-- inheritance
CREATE TABLE app.vehicle (id integer PRIMARY KEY, label text);
CREATE TABLE app.car (doors integer DEFAULT 4, color text) INHERITS (app.vehicle);
INSERT INTO app.vehicle VALUES (1, 'bike');
INSERT INTO app.car (id, label, doors, color) VALUES (2, 'sedan', 4, 'red'), (3, 'coupe', 2, 'blue');

-- unlogged with reloptions
CREATE UNLOGGED TABLE app.scratch (id integer PRIMARY KEY, note text) WITH (fillfactor = 70);
INSERT INTO app.scratch SELECT i, 'n' || i FROM generate_series(1, 20) i;

-- edge data
CREATE TABLE app.edge (id integer PRIMARY KEY, t text, b bytea);
INSERT INTO app.edge VALUES
  (1, E'tab\there', '\x00010203ff'),
  (2, E'new\nline and\r\ncrlf', '\x'),
  (3, E'back\\slash \\N \\x41', '\xdeadbeef00'),
  (4, NULL, NULL),
  (5, 'quote '' and " and ''''', '\x00'),
  (6, 'unicode: üñí 日本語 😀 Ωmega', '\x5c5c'),
  (7, '', '\x00000000'),
  (8, 'NULL', NULL);
CREATE TABLE app."Weird Table" ("select" integer, "from col" text, "Mixed""Quote" text);
INSERT INTO app."Weird Table" VALUES (1, 'a', 'b'), (2, NULL, 'c');
CREATE TABLE app.empty_table (id integer PRIMARY KEY, x text);
CREATE TABLE app.zero_cols ();

-- audit + notes
CREATE TABLE audit.log (id serial PRIMARY KEY, what text, at_n integer);
CREATE TABLE app.notes (id serial PRIMARY KEY, body text);

-- functions
CREATE FUNCTION app.add_plpgsql(a integer, b integer) RETURNS integer
  LANGUAGE plpgsql IMMUTABLE AS $f$ BEGIN RETURN a + b; END $f$;
CREATE FUNCTION app.add_sql(a integer, b integer) RETURNS integer
  LANGUAGE sql IMMUTABLE AS $f$ SELECT a + b $f$;
CREATE FUNCTION app.customer_label(c app.customers) RETURNS text
  LANGUAGE sql STABLE AS $f$ SELECT c.id || ': ' || c.name $f$;
COMMENT ON FUNCTION app.add_sql(integer, integer) IS 'adds; it''s "simple"';

DO $do$
BEGIN
  IF current_setting('server_version_num')::int >= 140000 THEN
    EXECUTE $q$
      CREATE FUNCTION app.atomic_double(x integer) RETURNS integer
      LANGUAGE sql IMMUTABLE
      BEGIN ATOMIC
        SELECT x * 2;
      END
    $q$;
  ELSE
    EXECUTE $q$
      CREATE FUNCTION app.atomic_double(x integer) RETURNS integer
      LANGUAGE sql IMMUTABLE AS 'SELECT x * 2'
    $q$;
  END IF;
END
$do$;

CREATE PROCEDURE app.add_note(p_body text)
  LANGUAGE plpgsql AS $p$ BEGIN INSERT INTO app.notes (body) VALUES (p_body); END $p$;

-- aggregate with SFUNC + INITCOND
CREATE FUNCTION app.sum_sq_step(state bigint, v integer) RETURNS bigint
  LANGUAGE sql IMMUTABLE AS $f$ SELECT state + v::bigint * v $f$;
CREATE AGGREGATE app.sum_squares(integer) (SFUNC = app.sum_sq_step, STYPE = bigint, INITCOND = '0');

-- views (B depends on A)
CREATE VIEW app.view_a AS SELECT id, email, score FROM app.customers WHERE score > 10;
CREATE VIEW app.view_b AS SELECT id, upper(email::text) AS email_up FROM app.view_a WHERE score < 40;

-- materialized view + unique index
CREATE MATERIALIZED VIEW "sales data".monthly_totals AS
  SELECT date_trunc('month', ordered_at) AS month, sum(amount) AS total, count(*) AS n
  FROM "sales data".orders GROUP BY 1;
CREATE UNIQUE INDEX monthly_totals_month_idx ON "sales data".monthly_totals (month);

-- triggers (one enabled, one disabled)
CREATE FUNCTION audit.log_customer() RETURNS trigger LANGUAGE plpgsql AS $f$
BEGIN
  INSERT INTO audit.log (what, at_n) VALUES (TG_OP || ' customer ' || NEW.id, 0);
  RETURN NEW;
END $f$;
CREATE TRIGGER customers_audit AFTER INSERT ON app.customers
  FOR EACH ROW EXECUTE FUNCTION audit.log_customer();
CREATE TRIGGER customers_audit_disabled AFTER UPDATE ON app.customers
  FOR EACH ROW EXECUTE FUNCTION audit.log_customer();
ALTER TABLE app.customers DISABLE TRIGGER customers_audit_disabled;

-- rule
CREATE RULE notes_log AS ON INSERT TO app.notes
  DO ALSO INSERT INTO audit.log (what, at_n) VALUES ('note inserted', NEW.id);
INSERT INTO app.notes (body) VALUES ('first'), ('second');

-- RLS
CREATE TABLE app.secrets (id serial PRIMARY KEY, owner_name text, secret text);
INSERT INTO app.secrets (owner_name, secret) VALUES ('pgbs_test_reader', 's1'), ('someone', 's2'), ('someone', 's3');
ALTER TABLE app.secrets ENABLE ROW LEVEL SECURITY;
CREATE POLICY secrets_owner ON app.secrets FOR SELECT USING (owner_name = current_user);
COMMENT ON POLICY secrets_owner ON app.secrets IS 'owner''s "own" rows';

-- grants
GRANT USAGE ON SCHEMA app, "sales data" TO pgbs_test_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA app TO pgbs_test_reader;
GRANT SELECT ON "sales data".orders, "sales data".orders_2024q1 TO pgbs_test_reader;
GRANT EXECUTE ON FUNCTION app.add_sql(integer, integer) TO pgbs_test_reader;

-- sequence values made distinctive
SELECT setval('app.customers_id_seq', 77) \gset
